/** The grading policy from docs/GRADING.md as data. */

import type { Category } from "./types.ts";

export const CATEGORIES: readonly Category[] = ["homework", "quizzes", "project", "exams"];

/** Category weights; they add up to 1. */
export const WEIGHTS: Readonly<Record<Category, number>> = {
  homework: 0.3,
  quizzes: 0.2,
  project: 0.2,
  exams: 0.3,
};

/** The lowest final percentage of each letter, best letter first. */
export const LETTER_BANDS: ReadonlyArray<readonly [number, string]> = [
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [80, "B-"],
  [77, "C+"],
  [73, "C"],
  [70, "C-"],
  [60, "D"],
  [0, "F"],
];

/** The points value of an excused assignment. */
export const EXCUSED = "EX";

/** Category percentages, final percentages, and letter grades. */

import { CATEGORIES, LETTER_BANDS, WEIGHTS } from "./policy.ts";
import type { CategoryPercents, ScoreRow, StudentResult } from "./types.ts";

/** A student's percentage over the rows of one category, or null when there are none. */
export function categoryPercent(rows: readonly ScoreRow[]): number | null {
  let earned = 0;
  let possible = 0;
  for (const row of rows) {
    earned += typeof row.points === "number" ? row.points : 0;
    possible += row.maxPoints;
  }
  return possible === 0 ? null : (100 * earned) / possible;
}

/** The weighted final percentage from a student's category percentages. */
export function finalPercent(categories: CategoryPercents): number {
  let total = 0;
  for (const category of CATEGORIES) {
    total += WEIGHTS[category] * (categories[category] ?? 0);
  }
  return total;
}

/** The letter grade for a final percentage. */
export function letterGrade(percent: number): string {
  const whole = Math.round(percent);
  for (const [lowest, letter] of LETTER_BANDS) {
    if (whole >= lowest) {
      return letter;
    }
  }
  return "F";
}

/** Every student's result, in student id order. */
export function gradeStudents(rows: readonly ScoreRow[]): StudentResult[] {
  const byStudent = new Map<string, ScoreRow[]>();
  for (const row of rows) {
    const list = byStudent.get(row.student) ?? [];
    list.push(row);
    byStudent.set(row.student, list);
  }
  const results: StudentResult[] = [];
  for (const student of [...byStudent.keys()].sort()) {
    const own = byStudent.get(student) ?? [];
    const categories = {} as CategoryPercents;
    for (const category of CATEGORIES) {
      categories[category] = categoryPercent(own.filter((row) => row.category === category));
    }
    const percent = finalPercent(categories);
    results.push({ student, name: own[0].name, categories, percent, letter: letterGrade(percent) });
  }
  return results;
}

/** Read assignment scores from CSV text. */

import { CATEGORIES, EXCUSED } from "./policy.ts";
import type { Category, Points, ScoreRow } from "./types.ts";

export const HEADER = "student,name,assignment,category,points,max_points";

/** A row that cannot be read as a score. */
export class ScoreError extends Error {
  line: number;

  constructor(line: number, message: string) {
    super(`line ${line}: ${message}`);
    this.name = "ScoreError";
    this.line = line;
  }
}

function parseNumber(text: string, line: number, field: string): number {
  const value = Number(text);
  if (text === "" || !Number.isFinite(value) || value < 0) {
    throw new ScoreError(line, `${field} must be a number of at least 0, got ${JSON.stringify(text)}`);
  }
  return value;
}

function parsePoints(text: string, line: number): Points {
  if (text === "") {
    return null;
  }
  if (text === EXCUSED) {
    return EXCUSED;
  }
  return parseNumber(text, line, "points");
}

/** Parse one data row; ``line`` is its 1-based line number in the file. */
export function parseRow(text: string, line: number): ScoreRow {
  const fields = text.split(",").map((field) => field.trim());
  if (fields.length !== 6) {
    throw new ScoreError(line, `expected 6 fields, got ${fields.length}`);
  }
  const [student, name, assignment, category, points, maxPoints] = fields;
  if (!student || !name || !assignment) {
    throw new ScoreError(line, "student, name, and assignment must not be empty");
  }
  if (!(CATEGORIES as readonly string[]).includes(category)) {
    throw new ScoreError(line, `unknown category ${JSON.stringify(category)}`);
  }
  const max = parseNumber(maxPoints, line, "max_points");
  if (max === 0) {
    throw new ScoreError(line, "max_points must be greater than 0");
  }
  return {
    student,
    name,
    assignment,
    category: category as Category,
    points: parsePoints(points, line),
    maxPoints: max,
    line,
  };
}

/** Parse a whole export; blank lines are skipped. */
export function parseScores(text: string): ScoreRow[] {
  const lines = text.split(/\r?\n/);
  const rows: ScoreRow[] = [];
  let headerSeen = false;
  lines.forEach((raw, index) => {
    const line = index + 1;
    if (raw.trim() === "") {
      return;
    }
    if (!headerSeen) {
      if (raw.trim() !== HEADER) {
        throw new ScoreError(line, `expected the header ${HEADER}`);
      }
      headerSeen = true;
      return;
    }
    rows.push(parseRow(raw, line));
  });
  return rows;
}

/** Command line: ``gradebook report FILE``. */

import { readFileSync } from "node:fs";
import { gradeStudents } from "./grades.ts";
import { renderReport } from "./report.ts";
import { ScoreError, parseScores } from "./scores.ts";

/** Where the command line writes its output. */
export interface Output {
  out: (text: string) => void;
  err: (text: string) => void;
}

const USAGE = "usage: gradebook report FILE\n";

/** Run the command line and return the exit status. */
export function main(argv: readonly string[], output: Output): number {
  if (argv.length !== 2 || argv[0] !== "report") {
    output.err(USAGE);
    return 2;
  }
  const file = argv[1];
  let text: string;
  try {
    text = readFileSync(file, "utf8");
  } catch {
    output.err(`gradebook: cannot read ${file}\n`);
    return 2;
  }
  try {
    output.out(renderReport(gradeStudents(parseScores(text))));
  } catch (error) {
    if (error instanceof ScoreError) {
      output.err(`gradebook: ${error.message}\n`);
      return 2;
    }
    throw error;
  }
  return 0;
}

